CREATE TABLE `registros_sismos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `hora` time NOT NULL,
  `magnitud` decimal(3,1) NOT NULL,
  `latitud` decimal(7,4) NOT NULL,
  `longitud` decimal(7,4) NOT NULL,
  `profundidad` decimal(5,1) NOT NULL,
  `referencia_localizacion` text,
  `fecha_utc` date NOT NULL,
  `hora_utc` time NOT NULL,
  `estatus` varchar(20) DEFAULT NULL,
  `placa_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_registros_sismos_placas_idx` (`placa_id`),
  CONSTRAINT `fk_registros_sismos_placas` FOREIGN KEY (`placa_id`) REFERENCES `placas` (`placa_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9563 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
